describe('Form Submit Button Disabled Until All Required Fields Are Filled', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should disable submit button when required fields are empty', () => {
    // Verify submit button is disabled initially
    cy.get('[data-testid="submit-button"]').should('be.disabled');
    cy.get('[data-testid="submit-button"]').should('contain', 'Submit');

    // Attempt to submit with empty fields
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission is prevented
    cy.get('[data-testid="form"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please fill out all required fields');

    // Verify submit button remains disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');
  });

  it('should enable submit button when all required fields are filled', () => {
    // Fill in all required fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john@example.com');
    cy.get('[data-testid="phone-input"]').type('555-123-465');

    // Verify submit button is now enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');
    cy.get('[data-testid="submit-button"]').should('contain', 'Submit');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Verify form submission success
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify form is cleared or redirected
    cy.get('[data-testid="form"]').should('not.exist');
  });
});
